import { RoutePlaybackConflictError, routePlaybackErrorStatus } from "./route-playback.js";
export function routePlaybackErrorResponse(error, status = routePlaybackErrorStatus(error)) {
    return Response.json({
        ok: false,
        error: error instanceof Error ? error.message : String(error)
    }, {
        status
    });
}
export async function startRoutePlaybackResponse(playback, request, isCurrent = ()=>true) {
    if (!isCurrent()) {
        return routePlaybackErrorResponse(new RoutePlaybackConflictError("device session changed before route playback start"));
    }
    try {
        const route = await playback.start(request);
        return Response.json({
            ok: true,
            route
        });
    } catch (error) {
        return routePlaybackErrorResponse(error);
    }
}
